section.programlisting:
package http 0.2.0

use http.Request.Request
use http.Response.Response
use http.Router.Router

procedure hello(req: ref[Request], mutable res: ref[Response])
{
    let name req.param("name")
    let text "hello, `name`"
    res.send_text(text.as_slice())
}

var app Router.create(Page.allocate_page())
app.get("/hello/{name}", &hello)
serve(app, 8080)

package http 0.2.0
use http.Request.Request use http.Response.Response use http.Router.Router
; waits ms milliseconds without holding a thread, then answers ms procedure delay(req: ref[Request], mutable res: ref[Response]) { let ms parse_int_prefix(req.param("ms")) Scheduler.sleep(ms) res.send_int(ms) }
mutable port: int 0 mutable waiting: int 0 mutable most: int 0 mutable answered: int 0
; one client: a request, then the answer up to the end of the connection procedure client() mutable waiting, most, answered { var s TcpStream.connect("127.0.0.1", port) s.write("GET /delay/100 HTTP/1.1\r\nHost: here\r\nConnection: close\r\n\r\n") waiting := waiting + 1 if waiting > most most := waiting var buf u8[256] let view Slice[u8](256, &buf[0]) var got: size_t 0 repeat { let n s.read(view.slice_from(got)) if n <= 0 break got := got + (n as size_t) } waiting := waiting - 1 s.close() if got > 12 and buf[9] = 50 and buf[10] = 48 and buf[11] = 48 answered := answered + 1 }
var app Router.create(Page.allocate_page()) app.get("/delay/{ms}", &delay) var l TcpListener.listen(0) port := l.port() let server start(app, l)
let clients Scheduler.create(Page.allocate_page()) var k 0 while k < 100 { Scheduler.spawn(&client) k := k + 1 } Scheduler.run()
server.shutdown() server.wait() print "`answered` of 100 answered, at most `most` waiting at once"
